from time import sleep, time
from example_config import *
from tablestore_agent_storage import AgentStorageClient


def create_knowledge_base(client, kb_name):
    request = {
        "knowledgeBaseName": kb_name,
        "subspace": False,
        "description": "this is a test knowledge base generated by agent storage example",
    }
    client.create_knowledge_base(request)
    print("create knowledge base: " + kb_name + " successfully")


def delete_knowledge_base(client, kb_name):
    request = {
        "knowledgeBaseName": kb_name,
    }
    client.delete_knowledge_base(request)
    print("delete knowledge base: " + kb_name + " successfully")


def upload_document(client, kb_name, document_path):
    request = {
        "knowledgeBaseName": kb_name,
        "documents": [
            {
                "filePath": document_path,
            }
        ]
    }
    print("upload document: " + document_path + " successfully")
    return client.upload_documents(request)


def retrieve(client, kb_name, retrieve_query):
    request = {
        "knowledgeBaseName": kb_name,
        "retrievalQuery": {
            "text": retrieve_query,
            "type": "TEXT"
        },
        "retrievalConfiguration": {
            "searchType": ["DENSE_VECTOR", "FULL_TEXT"],
            "denseVectorSearchConfiguration": {
                "numberOfResults": 10
            },
            "fullTextSearchConfiguration": {
                "numberOfResults": 10
            },
            "rerankingConfiguration": {
                "type": "RRF",
                "numberOfResults": 10,
                "rrfConfiguration": {
                    "denseVectorSearchWeight": 1.0,
                    "fullTextSearchWeight": 1.0,
                    "k": 60
                }
            }
        }
    }
    return client.retrieve(request)


def wait_for_document_ready(client, kb_name, doc_id, timeout=120):
    """Wait for document to be processed"""
    print("waiting for document to be ready...")
    start_time = time()
    while True:
        get_request = {
            "knowledgeBaseName": kb_name,
            "docId": doc_id
        }
        resp = client.get_document(get_request)
        if resp["code"] == "SUCCESS" and len(resp["data"]) > 0:
            status = resp["data"][0]["status"]
            if status == "completed":
                print("document is ready")
                sleep(10) # wait for data sync
                return True, resp["data"][0]
            elif status == "failed":
                raise Exception("upload document failed")
            print("document status: " + status)

        if time() - start_time > timeout:
            raise Exception("wait for document parse timeout")
        sleep(2)


if __name__ == '__main__':
    client = AgentStorageClient(
        access_key_id=ALIYUN_ACCESS_KEY_ID,
        access_key_secret=ALIYUN_ACCESS_KEY_SECRET,
        oss_endpoint=OSS_ENDPOINT,
        oss_bucket_name=OSS_BUCKET,
        ots_endpoint=OTS_ENDPOINT,
        ots_instance_name=OTS_INSTANCE
    )

    test_kb = "test_kb_" + str(int(time()))
    create_knowledge_base(client, test_kb)
    upload_response = upload_document(client, test_kb, "./README.md")
    doc_id = upload_response["data"]["documentDetails"][0]["docId"]
    wait_for_document_ready(client, test_kb, doc_id)
    retrieve_response = retrieve(client, test_kb, "What is Agent Storage?")
    print("retrieve result: " + str(retrieve_response))
    delete_knowledge_base(client, test_kb)
